<?php require_once __DIR__.'/_base.php'; $title='Providers'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $st=$pdo->query('SELECT p.*,u.status user_status FROM providers p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC');?><h2>Providers</h2><div class="service-card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Verification</th><th>Account</th><th></th></tr></thead><tbody><?php foreach($st->fetchAll() as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['email'])?></td><td><?=badge($p['verification_status'])?></td><td><?=badge($p['account_status'])?></td><td><a class="btn btn-sm btn-outline-success" href="provider-details.php?id=<?=$p['id']?>">View</a></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>